import{_ as a,c as n,a as s,o as r}from"./app-C1s5HV2F.js";const t={};function i(o,e){return r(),n("div",null,e[0]||(e[0]=[s('<h1 id="glossary" tabindex="-1"><a class="header-anchor" href="#glossary"><span>Glossary</span></a></h1><p>The glossary section provides definitions for key terms and concepts used in the OpenMadness JavaScript library, designed to help you understand its functionality for fast and intuitive array and math operations. Terms are listed alphabetically for easy reference.</p><h2 id="array" tabindex="-1"><a class="header-anchor" href="#array"><span>Array</span></a></h2><p>A data structure in JavaScript that stores an ordered collection of elements, which can be of any data type (e.g., numbers, strings, objects). OpenMadness provides methods to perform operations like filtering, sorting, and mapping on arrays efficiently.</p><h2 id="array-operation" tabindex="-1"><a class="header-anchor" href="#array-operation"><span>Array Operation</span></a></h2><p>A function or method that manipulates or processes an array, such as transforming elements, selecting subsets, or computing aggregate values. OpenMadness simplifies array operations with intuitive methods optimized for performance.</p><h2 id="asynchronous-operation" tabindex="-1"><a class="header-anchor" href="#asynchronous-operation"><span>Asynchronous Operation</span></a></h2><p>A task that runs independently of the main program flow, allowing other code to execute while waiting for completion (e.g., fetching data). OpenMadness focuses on synchronous array and math operations but can work with asynchronous data after resolution (e.g., using Promises).</p><h2 id="element" tabindex="-1"><a class="header-anchor" href="#element"><span>Element</span></a></h2><p>An individual item stored in an array, accessed by its index (a zero-based numerical position). OpenMadness methods often operate on array elements to perform tasks like filtering or transformation.</p><h2 id="filter" tabindex="-1"><a class="header-anchor" href="#filter"><span>Filter</span></a></h2><p>An array operation that creates a new array containing only elements that satisfy a specified condition. OpenMadness likely includes a filter method to select elements based on a user-defined criterion.</p><h2 id="index" tabindex="-1"><a class="header-anchor" href="#index"><span>Index</span></a></h2><p>A numerical position (starting at 0) that identifies an element’s location in an array. OpenMadness methods use indices to access or manipulate specific array elements.</p><h2 id="javascript" tabindex="-1"><a class="header-anchor" href="#javascript"><span>JavaScript</span></a></h2><p>A high-level, interpreted programming language used for web development and other applications. OpenMadness is built in JavaScript, leveraging its native array and math capabilities for ease of use. Library</p><p>A collection of pre-written code (functions, methods, or classes) that developers can use to perform common tasks. OpenMadness is a JavaScript library designed to simplify array and mathematical operations for beginners.</p><h2 id="map" tabindex="-1"><a class="header-anchor" href="#map"><span>Map</span></a></h2><p>An array operation that creates a new array by applying a function to each element of the original array. OpenMadness likely provides a map method to transform array elements efficiently.</p><h2 id="math-operation" tabindex="-1"><a class="header-anchor" href="#math-operation"><span>Math Operation</span></a></h2><p>A function that performs mathematical computations, such as addition, averaging, or statistical calculations. OpenMadness includes methods for fast and intuitive math operations on numbers or arrays.</p><h2 id="method" tabindex="-1"><a class="header-anchor" href="#method"><span>Method</span></a></h2><p>A function that belongs to an object or library, designed to perform a specific task. OpenMadness methods (e.g., for filtering or summing arrays) are accessible via the OpenMadness object.</p><h2 id="module" tabindex="-1"><a class="header-anchor" href="#module"><span>Module</span></a></h2><p>A reusable piece of JavaScript code, often exported as a single unit. OpenMadness is distributed as a module, installable via npm (e.g., npm install openmadness) or included via a script tag.</p><h2 id="npm" tabindex="-1"><a class="header-anchor" href="#npm"><span>npm</span></a></h2><p>Node Package Manager, a tool for installing and managing JavaScript libraries. OpenMadness can be installed using npm install openmadness for use in Node.js or browser projects.</p><h2 id="promise" tabindex="-1"><a class="header-anchor" href="#promise"><span>Promise</span></a></h2><p>A JavaScript object representing the eventual completion (or failure) of an asynchronous operation. While OpenMadness primarily handles synchronous operations, it can process data resolved from Promises.</p><h2 id="sort" tabindex="-1"><a class="header-anchor" href="#sort"><span>Sort</span></a></h2><p>An array operation that rearranges elements in a specified order (e.g., ascending or descending). OpenMadness includes a sort method to organize array elements based on user-defined criteria.</p><h2 id="synchronous-operation" tabindex="-1"><a class="header-anchor" href="#synchronous-operation"><span>Synchronous Operation</span></a></h2><p>A task that executes immediately and blocks further code execution until complete. OpenMadness focuses on synchronous operations for straightforward array and math processing.</p>',33)]))}const p=a(t,[["render",i]]),d=JSON.parse('{"path":"/resources/glossary.html","title":"Glossary","lang":"en-US","frontmatter":{"lang":"en-US","title":"Glossary","description":"Lookup common terms in Openmadness"},"headers":[{"level":2,"title":"Array","slug":"array","link":"#array","children":[]},{"level":2,"title":"Array Operation","slug":"array-operation","link":"#array-operation","children":[]},{"level":2,"title":"Asynchronous Operation","slug":"asynchronous-operation","link":"#asynchronous-operation","children":[]},{"level":2,"title":"Element","slug":"element","link":"#element","children":[]},{"level":2,"title":"Filter","slug":"filter","link":"#filter","children":[]},{"level":2,"title":"Index","slug":"index","link":"#index","children":[]},{"level":2,"title":"JavaScript","slug":"javascript","link":"#javascript","children":[]},{"level":2,"title":"Map","slug":"map","link":"#map","children":[]},{"level":2,"title":"Math Operation","slug":"math-operation","link":"#math-operation","children":[]},{"level":2,"title":"Method","slug":"method","link":"#method","children":[]},{"level":2,"title":"Module","slug":"module","link":"#module","children":[]},{"level":2,"title":"npm","slug":"npm","link":"#npm","children":[]},{"level":2,"title":"Promise","slug":"promise","link":"#promise","children":[]},{"level":2,"title":"Sort","slug":"sort","link":"#sort","children":[]},{"level":2,"title":"Synchronous Operation","slug":"synchronous-operation","link":"#synchronous-operation","children":[]}],"git":{"updatedTime":1752233059000,"contributors":[{"name":"Dev-Liz","username":"Dev-Liz","email":"basseyelizabeth569@gmail.com","commits":2,"url":"https://github.com/Dev-Liz"}],"changelog":[{"hash":"0acba5225b3b7241742c11f2eb31ec2dcd6ddd05","time":1752233059000,"email":"basseyelizabeth569@gmail.com","author":"Dev-Liz","message":"Updated content"},{"hash":"a6376b6867019658f19d5f27afd0cae5c3b98baa","time":1751456764000,"email":"basseyelizabeth569@gmail.com","author":"Dev-Liz","message":"updated docs"}]},"filePathRelative":"resources/glossary.md"}');export{p as comp,d as data};
